      ctx.lineWidth = 0.7; ctx.beginPath();
      for (let i = 0, x = r.x; x <= r.x + r.L + 0.01; i++, x = r.x + i * tk) { const major = i % 5 === 0; ctx.moveTo(x, r.y); ctx.lineTo(x, r.y + (major ? 8 : 4)); }
